import hashlib
import json
import sys
from html.parser import HTMLParser
from urllib.error import HTTPError, URLError
from urllib.parse import urljoin, urlsplit, urlunsplit
from urllib.request import HTTPRedirectHandler, Request, build_opener

START_URL = "http://192.168.5.0:8080/"
TIMEOUT_SECONDS = 15
USER_AGENT = "Mozilla/5.0 (compatible; HTTPFingerprint/1.0)"


class RedirectRecorder(HTTPRedirectHandler):
    def __init__(self):
        super().__init__()
        self.chain = []

    def redirect_request(self, req, fp, code, msg, headers, newurl):
        self.chain.append({"status": code, "from": req.full_url, "to": newurl})
        return super().redirect_request(req, fp, code, msg, headers, newurl)


class PageEvidence(HTMLParser):
    ASSET_RELATIONS = {"stylesheet", "icon", "shortcut", "apple-touch-icon", "preload", "modulepreload", "manifest"}

    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.title_parts = []
        self.in_title = False
        self.meta = []
        self.assets = []
        self.text_parts = []

    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        if tag.lower() == "title":
            self.in_title = True
        if tag.lower() == "meta":
            self.meta.append({"name": attrs.get("name") or attrs.get("property"), "content": attrs.get("content")})
        candidates = []
        tag = tag.lower()
        if tag == "script" and attrs.get("src"):
            candidates.append(("script", attrs["src"]))
        elif tag == "link" and attrs.get("href"):
            rels = set((attrs.get("rel") or "").lower().split())
            if rels & self.ASSET_RELATIONS:
                candidates.append(("link:" + " ".join(sorted(rels)), attrs["href"]))
        elif tag in {"img", "iframe", "embed", "audio", "video", "source"}:
            if attrs.get("src"):
                candidates.append((tag, attrs["src"]))
            if tag == "video" and attrs.get("poster"):
                candidates.append(("video-poster", attrs["poster"]))
            if attrs.get("srcset"):
                for item in attrs["srcset"].split(","):
                    candidate = item.strip().split()
                    if candidate:
                        candidates.append((tag + "-srcset", candidate[0]))
        self.assets.extend({"kind": kind, "reference": ref} for kind, ref in candidates if ref)

    def handle_endtag(self, tag):
        if tag.lower() == "title":
            self.in_title = False

    def handle_data(self, data):
        if self.in_title:
            self.title_parts.append(data)
        stripped = data.strip()
        if stripped:
            self.text_parts.append(stripped)


def decode_body(body, headers):
    charset = None
    try:
        charset = headers.get_content_charset()
    except Exception:
        pass
    if not charset:
        charset = "utf-8"
    try:
        return body.decode(charset, errors="replace"), charset
    except LookupError:
        return body.decode("utf-8", errors="replace"), "utf-8 (fallback; declared charset unknown)"


def get_response(url):
    recorder = RedirectRecorder()
    opener = build_opener(recorder)
    request = Request(url, headers={"User-Agent": USER_AGENT, "Accept-Encoding": "identity", "Accept": "text/html,application/xhtml+xml,application/xml,*/*;q=0.8"}, method="GET")
    try:
        response = opener.open(request, timeout=TIMEOUT_SECONDS)
    except HTTPError as exc:
        response = exc
    except (URLError, OSError, ValueError) as exc:
        return {"requested_url": url, "status": "request_error", "error_type": type(exc).__name__, "error": str(exc), "redirect_chain": recorder.chain}
    try:
        body = response.read()
        headers = response.headers
        code = response.getcode()
        final_url = response.geturl()
        header_items = list(headers.items())
        content_type = headers.get("Content-Type")
        text, charset = decode_body(body, headers)
        result = {
            "requested_url": url,
            "status": code,
            "reason": getattr(response, "reason", None),
            "final_url": final_url,
            "redirect_chain": recorder.chain,
            "headers": header_items,
            "content_type": content_type,
            "body_bytes": len(body),
            "body_sha256": hashlib.sha256(body).hexdigest(),
            "charset_used": charset,
            "body_text_sample": text[:6000],
            "body_text_sample_truncated": len(text) > 6000,
            "_body": body,
            "_text": text,
            "_headers": headers,
        }
        return result
    except (OSError, ValueError) as exc:
        return {"requested_url": url, "status": "response_read_error", "error_type": type(exc).__name__, "error": str(exc), "redirect_chain": recorder.chain}
    finally:
        try:
            response.close()
        except Exception:
            pass


def origin(url):
    parts = urlsplit(url)
    scheme = parts.scheme.lower()
    host = (parts.hostname or "").lower()
    try:
        port = parts.port
    except ValueError:
        return None
    if port is None:
        port = 80 if scheme == "http" else 443 if scheme == "https" else None
    return (scheme, host, port)


def public_response(record):
    return {key: value for key, value in record.items() if not key.startswith("_")}


def main():
    output = {"target": START_URL, "method": "GET", "scope_note": "Only the specified endpoint and directly linked assets with the same scheme, host, and port are requested.", "initial_response": None, "page_fingerprints": {}, "linked_assets": []}
    page = get_response(START_URL)
    output["initial_response"] = public_response(page)
    if "_text" not in page:
        print(json.dumps(output, ensure_ascii=False))
        return

    page_evidence = PageEvidence()
    content_type = (page.get("content_type") or "").lower()
    if "html" in content_type or "xml" in content_type or "<html" in page["_text"][:1000].lower():
        try:
            page_evidence.feed(page["_text"])
            page_evidence.close()
            output["page_fingerprints"] = {
                "title": " ".join(" ".join(page_evidence.title_parts).split()) or None,
                "meta": page_evidence.meta,
                "visible_text_sample": " ".join(page_evidence.text_parts)[:4000],
                "direct_asset_references_found": len(page_evidence.assets),
            }
        except Exception as exc:
            output["page_fingerprints"] = {"html_parse_error": type(exc).__name__ + ": " + str(exc), "direct_asset_references_found": 0}
    else:
        output["page_fingerprints"] = {"note": "Response was not identified as HTML/XML; no HTML asset extraction attempted.", "direct_asset_references_found": 0}

    base = page.get("final_url") or START_URL
    base_origin = origin(base)
    seen = set()
    for item in page_evidence.assets:
        absolute = urljoin(base, item["reference"])
        parts = urlsplit(absolute)
        normalized = urlunsplit((parts.scheme, parts.netloc, parts.path or "/", parts.query, ""))
        if normalized in seen:
            continue
        seen.add(normalized)
        if parts.scheme.lower() not in {"http", "https"} or origin(normalized) != base_origin:
            output["linked_assets"].append({"kind": item["kind"], "url": normalized, "status": "not_requested", "reason": "Not an HTTP(S) asset on the response page's same origin."})
            continue
        asset = get_response(normalized)
        record = {"kind": item["kind"], "url": normalized, "response": public_response(asset)}
        if "_body" in asset:
            body = asset["_body"]
            text, charset = decode_body(body, asset["_headers"])
            record["response"]["charset_used"] = charset
            record["response"]["body_text_sample"] = text[:6000]
            record["response"]["body_text_sample_truncated"] = len(text) > 6000
        output["linked_assets"].append(record)

    print(json.dumps(output, ensure_ascii=False))


if __name__ == "__main__":
    main()

