import json
import re
import sys

try:
    from framework_evidence import run_tool
except Exception as exc:
    print(json.dumps({"error": "Could not load the supplied framework evidence helper", "detail": str(exc)}))
    sys.exit(1)


def envelope_text(value):
    """Collect tool output text without replacing the raw evidence envelope."""
    found = []
    if isinstance(value, dict):
        for key, item in value.items():
            if key in ("stdout", "stderr") and isinstance(item, str):
                found.append(item)
            else:
                found.extend(envelope_text(item))
    elif isinstance(value, list):
        for item in value:
            found.extend(envelope_text(item))
    return found


def call_console(command):
    argv = ["msfconsole", "-q", "-x", command + "; exit"]
    try:
        return run_tool(argv)
    except Exception as exc:
        return {"command": argv, "status": "helper_error", "error": str(exc)}


search = call_console("search type:exploit geoserver")
search_text = "\n".join(envelope_text(search))
# Only inspect module paths explicitly appearing in the actual search output.
pattern = re.compile(r"(?<![A-Za-z0-9_./-])exploit/[A-Za-z0-9_./-]*geoserver[A-Za-z0-9_./-]*", re.IGNORECASE)
candidates = sorted(set(pattern.findall(search_text)), key=str.lower)

# Preserve each helper-returned envelope verbatim as JSON output. The commands
# are limited to module information queries; no exploit or payload is run.
print(json.dumps({"phase": "search", "evidence_envelope": search}, ensure_ascii=False))
inspections = []
for module in candidates:
    result = call_console("info " + module)
    inspections.append({"module": module, "evidence_envelope": result})
    print(json.dumps({"phase": "module_info", "module": module, "evidence_envelope": result}, ensure_ascii=False))

print(json.dumps({
    "assessment_inputs": {
        "task_supplied_application_evidence": "GeoServer at 192.168.5.0:8080",
        "search_query": "search type:exploit geoserver",
        "candidate_modules_extracted_from_console_output": candidates,
        "module_info_queries_completed": len(inspections),
        "note": "Candidates and their descriptions/options are evidence for assessment, not proof of compatibility. No exploit was executed. If candidates is empty, the captured search output did not yield a matching exploit module path."
    }
}, ensure_ascii=False))
